package com.nook.widgets;

import android.content.Context;
import android.graphics.*;
import android.view.View;
import android.widget.RemoteViews;
import org.json.JSONObject;

/** Original paired-earpiece illustration and honest source-labeled gauges. */
public final class BudsWidgets {
    private BudsWidgets(){}
    public static String[] variants(){return new String[]{"Dark Stage","Glass Gauge","Minimal Pods"};}
    public static Bitmap scene(BudsData.State state,int variant,int accent,int ink,int muted){
        Bitmap bitmap=Bitmap.createBitmap(480,180,Bitmap.Config.ARGB_8888);bitmap.setDensity(Bitmap.DENSITY_NONE);Canvas c=new Canvas(bitmap);Paint p=new Paint(3);
        for(int side=0;side<2;side++){float x=side==0?89:391;int level=state.manual?(side==0?state.left:state.right):state.battery;RectF ring=new RectF(x-61,23,x+61,145);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(6);p.setStrokeCap(Paint.Cap.ROUND);p.setColor(0xff303a32);c.drawArc(ring,135,270,false,p);if(level>=0){p.setShader(new LinearGradient(x-60,140,x+60,20,new int[]{MusicArt.mix(accent,Color.BLACK,.4f),accent},null,Shader.TileMode.CLAMP));c.drawArc(ring,135,270*level/100f,false,p);p.setShader(null);}p.setStyle(Paint.Style.FILL);c.save();c.translate(x,81);c.rotate(side==0?-23:23);p.setShadowLayer(6,1,4,0x60000000);p.setShader(new LinearGradient(-23,-25,22,45,new int[]{0xffffffff,0xffd5dede},null,Shader.TileMode.CLAMP));c.drawRoundRect(-6,-2,10,60,8,8,p);c.drawOval(-27,-23,24,14,p);p.clearShadowLayer();p.setShader(null);p.setColor(0xff2d3537);c.drawOval(side==0?-22:6,-13,side==0?-11:17,-2,p);p.setColor(0xffb5c0c4);c.drawRoundRect(-2,50,7,55,3,3,p);c.restore();p.setTextAlign(Paint.Align.CENTER);p.setTypeface(Typeface.create("sans-serif-medium",0));p.setTextSize(18);p.setColor(muted);c.drawText((side==0?"L  ":"R  ")+(state.manual?BudsData.value(level):"—"),x,171,p);}
        p.setTextAlign(Paint.Align.CENTER);p.setColor(ink);p.setTextSize(36);p.setTypeface(Typeface.create("sans-serif-light",0));c.drawText(BudsData.value(state.battery),240,80,p);p.setTextSize(14);p.setColor(muted);c.drawText(state.manual?"MANUAL":"COMBINED",240,102,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);c.drawRoundRect(219,117,261,140,8,8,p);p.setStyle(Paint.Style.FILL);c.drawCircle(240,133,2,p);p.setTextSize(16);c.drawText("Case "+BudsData.value(state.caseLevel),240,162,p);return bitmap;
    }
    public static RemoteViews render(Context c,int id,JSONObject config,boolean small,boolean preview){
        if(!preview)BudsData.refresh(c);BudsData.State state=BudsData.read(c,config);int variant=WidgetDesign.clamp(config.optInt("variant",0),0,2);RemoteViews v=new RemoteViews(c.getPackageName(),WidgetDesign.layout(c,"widget_buds",config));int text=variant==2?0xff16261b:0xfff2fff2,muted=variant==2?0xff4b6252:0xffa1b9a7,accent=0xff66df84;WidgetDesign.Colors colors=WidgetDesign.colors(config,"buds");boolean themed=WidgetDesign.id(config)>0||config.optInt("style",0)>0;if(themed){text=colors.text;muted=colors.muted;accent=colors.accent;}
        v.setImageViewResource(R.id.widget_surface,Widgets.surfaceResource(config,"buds"));WidgetDesign.surfaces(c,v,id,"buds",config,small,new int[]{});int[] size=WidgetDesign.size(c,id,"buds",config,small);if(config.optInt("style",0)==0&&!themed)v.setImageViewBitmap(R.id.widget_surface,CreativeArt.panel(variant==2?0xffe4efe6:0xff050907,320,320*size[1]/size[0],WidgetDesign.radius(config)*320f/size[0],false));v.setInt(R.id.widget_surface,"setImageAlpha",Widgets.surfaceAlpha(config));
        v.setTextViewText(R.id.widget_label,"BUDS · "+variants()[variant].toUpperCase(java.util.Locale.ROOT));v.setTextViewText(R.id.widget_title,config.optString("title","").isEmpty()?state.name:config.optString("title"));v.setTextViewText(R.id.buds_status,state.status);v.setTextViewText(R.id.widget_meta,state.source);v.setTextColor(R.id.widget_title,text);v.setTextColor(R.id.widget_label,muted);v.setTextColor(R.id.buds_status,state.online?accent:muted);v.setTextColor(R.id.widget_meta,muted);v.setInt(R.id.widget_settings,"setColorFilter",text);v.setImageViewBitmap(R.id.buds_scene,scene(state,variant,accent,text,muted));v.setViewVisibility(R.id.widget_header,config.optBoolean("budsHideTitle",false)||size[1]<180?View.GONE:View.VISIBLE);v.setViewVisibility(R.id.widget_title,config.optBoolean("budsHideTitle",false)?View.GONE:View.VISIBLE);v.setViewVisibility(R.id.widget_label,config.optBoolean("showLabel",true)?View.VISIBLE:View.GONE);v.setTextViewTextSize(R.id.widget_title,android.util.TypedValue.COMPLEX_UNIT_SP,(size[1]<180?14:18)*WidgetDesign.scale(config));
        if(size[1]<180)v.setViewPadding(R.id.widget_root,Ui.dp(c,10),Ui.dp(c,8),Ui.dp(c,10),Ui.dp(c,8));v.setContentDescription(R.id.buds_scene,"Combined "+BudsData.value(state.battery)+". Left "+BudsData.value(state.left)+". Right "+BudsData.value(state.right)+". Case "+BudsData.value(state.caseLevel)+". "+state.source);if(!preview){v.setOnClickPendingIntent(R.id.widget_root,LibraryWidgets.configure(c,id,"buds"));v.setOnClickPendingIntent(R.id.widget_settings,LibraryWidgets.configure(c,id,"buds"));}return v;
    }
}
